import{u as i,j as e}from"./index-DmR14ezO.js";import{L as t,a}from"./LegalDoc-dtpep_UK.js";import"./Seo-CxfBSQzc.js";import"./cloudinary-C4FyQwY9.js";const s="grupoinmobiliario3i.ec@gmail.com",o=e.jsx("a",{href:`mailto:${s}`,className:"text-accent underline",children:s}),n={seoTitle:"Política de privacidad",seoDesc:"Qué datos recoge Grupo 3i, para qué los usa, con quién los comparte y cómo ejercer tus derechos.",title:"Política de privacidad y cookies",updated:"Última actualización: octubre de 2026",intro:"En Grupo 3i cuidamos los datos que nos confías. Aquí te explicamos, sin letra pequeña, qué datos recogemos, para qué los usamos, con quién los compartimos y cómo puedes pedirnos que los corrijamos o los borremos.",sections:[{title:"1. Quién es responsable de tus datos",body:[e.jsxs(e.Fragment,{children:["Grupo 3i, grupo inmobiliario con operaciones en Manglaralto, provincia de Santa Elena, Ecuador. Para cualquier tema de privacidad escríbenos a ",o," o por WhatsApp al +593 98 487 5050."]})]},{title:"2. Qué datos recogemos",body:["Solo los que necesitamos para atenderte:",e.jsx(a,{items:[e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Cuando nos escribes o pides información"})," (formularios de contacto, de un proyecto o de un lote): tu nombre, tu número de WhatsApp, tu email si lo das, tu mensaje y el proyecto o lote que te interesa."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Si te registras en Refiere y gana"}),": además, tu documento de identidad (cédula o pasaporte) y tus datos para recibir pagos (cuenta bancaria, PayPal, Payoneer o Wise). Los pedimos para poder pagarte tus comisiones."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Si eres una desarrolladora"}),": los datos de tu empresa y de tu equipo, y los documentos legales de tu proyecto, que se guardan en privado."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Si compras un producto"}),": los datos de la compra."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Cómo usas el sitio"}),": qué páginas, proyectos y lotes miras, desde qué tipo de dispositivo y en qué idioma, y de qué anuncio o enlace llegaste. Lo medimos con un identificador anónimo, sin tu nombre."]})]}),"Tu ubicación en el mapa de lotes se calcula solo en tu teléfono, únicamente si la activas, y no la guardamos."]},{title:"3. Para qué los usamos",body:[e.jsx(a,{items:["Responderte y darte la información que pediste, normalmente por WhatsApp.","Gestionar compras, reservas, membresías y pagos.","Pagar las comisiones de Refiere y gana y verificar la identidad de quien las cobra.","Saber qué anuncios y páginas funcionan, para mejorar el sitio y nuestras campañas.","Cumplir obligaciones legales y prevenir fraudes."]}),"No vendemos tus datos ni los usamos para nada distinto de lo que dice esta política."]},{title:"4. Con quién los compartimos",body:[e.jsx(a,{items:[e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"La desarrolladora del proyecto que te interesa."})," Si preguntas por un proyecto de una desarrolladora aliada, tu nombre, tu WhatsApp y tu mensaje llegan a ella y a su asesor, para que te atiendan."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"El socio que te recomendó"}),", si llegaste por un enlace de Refiere y gana: puede ver que te registraste o compraste, para saber que su comisión está en camino."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Proveedores que hacen funcionar el sitio"}),": alojamiento y base de datos (Railway), imágenes (Cloudinary), envío de correos (Resend) y mensajería (WhatsApp). Solo usan los datos para prestarnos ese servicio."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Google, Meta y TikTok"}),", solo si aceptas las cookies de medición (ver la sección 6)."]}),"Autoridades, cuando la ley nos obliga."]}),"Algunos de estos proveedores guardan datos fuera del Ecuador. Trabajamos con empresas que ofrecen garantías adecuadas de protección."]},{title:"5. Cuánto tiempo los guardamos",body:["Mientras exista una relación contigo (una consulta abierta, una compra, una membresía o una cuenta activa) y, después, el tiempo que exija la ley, por ejemplo para fines tributarios. Los contactos que no avanzan se archivan y puedes pedir que se borren en cualquier momento."]},{title:"6. Cookies y medición",body:["Usamos dos tipos:",e.jsx(a,{items:[e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Necesarias"}),": recuerdan tu idioma, si iniciaste sesión, tu elección sobre las cookies y, durante 30 días, el anuncio o enlace por el que llegaste. También guardamos un identificador anónimo para contar visitas. Sin ellas el sitio no funciona bien."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"De medición y publicidad"})," (Google Analytics, Google Ads, Meta y TikTok): nos dicen qué anuncios traen clientes. ",e.jsx("b",{children:"Solo se activan si eliges «Aceptar todas»"})," en el aviso de cookies."]})]}),"Puedes cambiar de opinión borrando los datos del sitio en tu navegador: el aviso volverá a aparecer."]},{title:"7. Tus derechos",body:["Según la Ley Orgánica de Protección de Datos Personales del Ecuador, puedes pedirnos en cualquier momento:",e.jsx(a,{items:["Saber qué datos tuyos tenemos (acceso).","Corregirlos si están mal (rectificación).","Borrarlos (eliminación).","Que dejemos de usarlos para algo en particular, como enviarte novedades (oposición).","Recibirlos en un formato que puedas llevar a otro lugar (portabilidad)."]}),e.jsxs(e.Fragment,{children:["Escríbenos a ",o," desde el correo o el WhatsApp con el que te registraste. Te respondemos en un máximo de 15 días. Si no quedas conforme, puedes acudir a la Superintendencia de Protección de Datos Personales."]})]},{title:"8. Seguridad",body:["Los datos viajan cifrados (https), las contraseñas se guardan cifradas y cada persona del equipo ve solo lo que necesita para su trabajo. Los documentos legales de las desarrolladoras se guardan en privado y sus enlaces de consulta caducan en minutos."]},{title:"9. Menores de edad",body:["El sitio está dirigido a mayores de edad. Para registrarse en Refiere y gana o comprar hay que ser mayor de 18 años."]},{title:"10. Cambios a esta política",body:[e.jsx(e.Fragment,{children:"Si cambiamos algo importante, lo publicaremos aquí con la nueva fecha. Las reglas del programa de referidos están en el reglamento de Refiere y gana, que cada socio tiene en su oficina virtual, y las de la adopción de árboles en los términos del Bosque Montañita."})]}]},d={seoTitle:"Privacy policy",seoDesc:"What data Grupo 3i collects, how we use it, who we share it with and how to exercise your rights.",title:"Privacy and cookie policy",updated:"Last updated: October 2026",intro:"At Grupo 3i, we take care of the information you trust us with. This page explains — in plain language — what we collect, why, who we share it with, and how you can ask us to correct or delete it.",sections:[{title:"1. Who we are",body:[e.jsxs(e.Fragment,{children:["Grupo 3i is a real estate group operating in Manglaralto, Santa Elena province, Ecuador. For anything privacy-related, email ",o," or message us on WhatsApp at +593 98 487 5050."]})]},{title:"2. What we collect",body:["Only what we need to help you:",e.jsx(a,{items:[e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"When you contact us or request information"})," (contact, project or lot forms): your name, WhatsApp number, email if you give it, your message and the project or lot you’re interested in."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"If you join Refer & Earn"}),": also your ID (Ecuadorian cédula or passport) and your payout details (bank account, PayPal, Payoneer or Wise), so we can pay your commissions."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"If you’re a developer"}),": your company and team details, and your project’s legal documents, which are stored privately."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"If you buy a product"}),": the purchase details."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"How you use the site"}),": which pages, projects and lots you view, what kind of device and language you use, and which ad or link brought you here. We track this with an anonymous ID, not your name."]})]}),"If you turn on your location on the lot map, it’s calculated on your phone only, and we never store it."]},{title:"3. How we use it",body:[e.jsx(a,{items:["To reply and send you the information you asked for — usually on WhatsApp.","To handle purchases, bookings, memberships and payments.","To pay Refer & Earn commissions and verify who’s receiving them.","To see which ads and pages work, so we can improve the site and our campaigns.","To meet legal requirements and prevent fraud."]}),"We never sell your data or use it for anything not described here."]},{title:"4. Who we share it with",body:[e.jsx(a,{items:[e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"The developer of the project you’re interested in."})," If you ask about a partner developer’s project, your name, WhatsApp number and message go to them and their agent so they can help you."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"The member who referred you"}),", if you came through a Refer & Earn link: they can see that you signed up or made a purchase, so they know their commission is on the way."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Service providers that keep the site running"}),": hosting and database (Railway), images (Cloudinary), email delivery (Resend) and messaging (WhatsApp). They only use your data to provide those services to us."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Google, Meta and TikTok"}),", only if you accept tracking cookies (see section 6)."]}),"Government authorities, when the law requires it."]}),"Some of these providers store data outside Ecuador. We only work with companies that offer appropriate safeguards."]},{title:"5. How long we keep it",body:["For as long as we have a relationship with you — an open inquiry, a purchase, a membership or an active account — and afterward for as long as the law requires, for example for tax purposes. Inquiries that don’t move forward are archived, and you can ask us to delete them at any time."]},{title:"6. Cookies and tracking",body:["We use two kinds:",e.jsx(a,{items:[e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Essential"}),": they remember your language, whether you’re signed in, your cookie choice and, for 30 days, the ad or link that brought you here. We also store an anonymous ID to count visits. The site doesn’t work properly without them."]}),e.jsxs(e.Fragment,{children:[e.jsx("b",{children:"Analytics and advertising"})," (Google Analytics, Google Ads, Meta and TikTok): they tell us which ads bring in customers. ",e.jsx("b",{children:"They’re only turned on if you choose “Accept all”"})," in the cookie banner."]})]}),"Changed your mind? Clear this site’s data in your browser and the banner will show up again."]},{title:"7. Your rights",body:["Under Ecuador’s Personal Data Protection Law, you can ask us at any time to:",e.jsx(a,{items:["Tell you what data we have about you (access).","Fix anything that’s wrong (correction).","Delete it (erasure).","Stop using it for a specific purpose, such as sending you updates (objection).","Send it to you in a format you can take elsewhere (portability)."]}),e.jsxs(e.Fragment,{children:["Email ",o," from the email or WhatsApp number you registered with. We’ll reply within 15 days. If you’re not satisfied, you can file a complaint with Ecuador’s Superintendency of Personal Data Protection."]})]},{title:"8. Security",body:["Data is encrypted in transit (https), passwords are stored encrypted, and each team member only sees what they need to do their job. Developers’ legal documents are stored privately, and links to view them expire within minutes."]},{title:"9. Minors",body:["This site is intended for adults. You must be 18 or older to join Refer & Earn or make a purchase."]},{title:"10. Changes to this policy",body:[e.jsx(e.Fragment,{children:"If we make an important change, we’ll post it here with a new date. The referral program rules are in the Refer & Earn program rules, available to every member in their Virtual Office, and the tree adoption rules are in the Bosque Montañita terms."})]}]};function p(){const{lang:r}=i();return e.jsx(t,{doc:r==="en"?d:n})}export{p as default};
